files.agent-pane/theme.css:
/* The starter chat style. Only cmux.agentPane.style/1 tokens (schemas/agent-pane/style-tokens.json)
   on :root: paint only, so nothing in the transcript moves when it applies. Every color is mixed
   from the theme's own (--agent-text, --agent-accent, --agent-page-bg). */
:root {
  --cv-user-bubble-tint: color-mix(in srgb, var(--agent-text) 6%, transparent);
  --cv-user-bubble-edge: transparent;
  --cv-user-bubble-radius: 14px;
  --cv-card-fill: color-mix(in srgb, var(--agent-text) 4%, transparent);
  --cv-card-ring: color-mix(in srgb, var(--agent-text) 9%, transparent);
  --cv-text-muted: color-mix(in srgb, var(--agent-text) 72%, transparent);
  --cv-link: color-mix(in srgb, var(--agent-accent) 80%, var(--agent-text));
  --agent-link: color-mix(in srgb, var(--agent-accent) 80%, var(--agent-text));
}

files.markdown/theme.css:
/* The starter Markdown style. Only --cmux-md-* custom properties on :root; every color is mixed
   from the page's own, so it reads over a light and a dark theme alike. */
:root {
  --cmux-md-code-background: color-mix(in srgb, var(--page-text) 5%, transparent);
  --cmux-md-code-radius: 10px;
  --cmux-md-heading-weight: 600;
  --cmux-md-heading-rule: none;
  --cmux-md-quote-border: 3px solid var(--cmux-md-border-color);
}
